/* ============ Original-Spielkonstanten (Xenon 2, umgerechnet auf NGPC) ============ */
/* Aus dem Original-Code ermittelt, Tick(18.21Hz)->Frame(60Hz) und px-Skalierung (x0.5)
   bereits eingerechnet. Geschwindigkeiten als Klartext-Bruch (kein 4.4-Fixed wie bei
   Pfaddaten — dafuer bei diesen kleinen Werten zu ungenau, 18%+ Fehler); selbst in ein
   passendes Fixed-Format wandeln, falls fuer die eigene Positionsberechnung gebraucht.
   Reine Referenzwerte -- an die eigene Umsetzung anpassen, wo sinnvoll (siehe Todes-
   Sperrzeit-Kommentar unten). Ausfuehrliche Tabelle mit Original-Rohwerten im Info-Tab. */
#define LVL_SCROLL_SPEED_PX_PER_256F   39   /* 0.152 px/Frame = 39/256 (Original: 1px/Tick) */
#define LVL_SCROLL_BACK_SLACK_PX       8    /* Original: 16px */
#define LVL_SCROLL_RAMP_FRAMES         112  /* Original: 34 Ticks bis Scroll sich verdoppelt */
#define LVL_SHIP_SPEED_Y_PX_PER_256F   { 116, 155, 194 }  /* Stufe 0/1/2 (Original: 3/4/5 px/Tick) */
#define LVL_SHIP_TILT_MAX_PX_PER_256F  233  /* 0.91 px/Frame (Original: 6px/Tick) */
#define LVL_SHIP_START_ENERGY          39   /* unveraendert, reiner Zaehler */
#define LVL_SHIP_START_LIVES           3
#define LVL_SHIP_MAX_LIVES             9
#define LVL_ENEMY_SHOT_DAMAGE          4
#define LVL_ENEMY_CONTACT_DAMAGE       8    /* 16 bei tough-Gegnern */
#define LVL_WALL_CRUSH_THRESHOLD       -17  /* Tick-Zaehler bis Sofort-Tod bei Wandkontakt */
#define LVL_BASE_FIRE_PERIOD_FRAMES    26   /* = Feuerraten-Stufe 0 (Original: 8 Ticks) */
#define LVL_SHIP_SHOT_SPEED_PX_PER_256F 349 /* 1.365 px/Frame (Original: 9px/Tick) */
#define LVL_ENEMY_SHOT_SPEED_PX_PER_256F 233 /* 0.91 px/Frame (Original: 6px/Tick, alle Gegner+Tuerme einheitlich) */
#define LVL_DIVE_DURATION_FRAMES       448  /* Original: 0x88 Ticks */
#define LVL_DIVE_CHARGES_PER_PICKUP    3
#define LVL_COMPANION_SHIELD_FRAMES    560  /* Original: 0xAA Ticks, stapelt bei Mehrfach-Pickup */
#define LVL_NASHWAN_FRAMES             560  /* Original: 0xAA Ticks */
#define LVL_HIT_FLASH_FRAMES           26   /* Original: 8 Ticks */
#define LVL_READY_CARD_FRAMES          329  /* Original: 100 Ticks, Schuss ueberspringt */
#define LVL_CASH_VALUE                 50   /* normale Wellen-Belohnung */
#define LVL_CASH_VALUE_BIG             100  /* tough-Wellen-Belohnung */
/* *_PX_PER_256F Werte: tatsaechliche Bewegung = Wert/256 px pro Frame (praeziser als
   4.4-Fixed bei diesen kleinen Geschwindigkeiten) -- x_accum += wert; x = x_accum>>8; */
/* Todes-Sperrzeit: im Original ~16 Ticks (53 NGPC-Frames), gaengige Ports verlaengern
   das bewusst auf die volle Explosions-Animationslaenge -- kein fester Wert hier,
   an die eigene Explosions-Animation koppeln statt eine Zahl fest zu uebernehmen. */
