/* ============ Scroll-Verhalten ============ */
/* LVL_SCROLL_END_ROW: Zeile, ab der NICHT weiter vorwärts (nach oben) gescrollt wird —
   Kamera/Scroll-Position dort hart deckeln, sobald sie diese Zeile erreicht (z.B. für
   eine Boss-Arena, die stehen bleiben soll, oder um Rand-Zeilen abzuschneiden).
   LVL_FREE_ZONE_*: Zeilenbereiche (inklusive), in denen die sonst übliche Regel
   "nicht beliebig weit zurückscrollen" AUSGESETZT ist — z.B. ein Shop-Abschnitt, in
   dem frei hin- und zurückgeflogen werden darf. Prüfen: aktuelle Zeile in IRGENDEINER
   Zone -> normales Rückwärts-Limit (falls vorhanden) ignorieren, sonst wie gehabt. */
#define LVL_SCROLL_END_ROW 292
#define LVL_FREE_ZONE_COUNT 3
const u16 lvl_free_zone_row_from[3] = { 105, 78, 270 };
const u16 lvl_free_zone_row_to[3] = { 126, 104, 292 };
/* Zonen: 0="unbenannt" (Zeile 105-126), 1="unbenannt" (Zeile 78-104), 2="unbenannt" (Zeile 270-292) */

/* ============ Tile-Animationen ============ */
/* Map-Zellen mit gesetztem a-Bit (bit 14) und Tile-Nr == lvl_anim_head[i] gehoeren zu Animation i.
   Laufzeit: pro Animation i alle (lvl_anim_speed[i]) Frames zum naechsten Bild schalten:
     frame = (frame + 1) % lvl_anim_len[i];  N = lvl_anim_frames[i][frame];
     dann fuer jede animierte Zelle die Map-Eintraege beider Ebenen neu schreiben:
     SCR2: SCR_ENTRY(TILE_BASE+lvl_tile_a_idx[N-1], lvl_tile_a_pal[N-1], hflip, 0)
     SCR1: SCR_ENTRY(TILE_BASE+lvl_tile_b_idx[N-1], lvl_tile_b_pal[N-1], hflip, 0)
   (hflip = f-Bit der Zelle; animierte Zellen beim Map-Aufbau in eine Liste sammeln.) */
#define LVL_ANIM_COUNT 5
#define LVL_ANIM_MAX_FRAMES 3
const u16 lvl_anim_head[5]  = { 109, 110, 115, 116, 138 };
const u8  lvl_anim_speed[5] = { 20, 20, 20, 20, 20 };  /* Frames (1/60s) pro Bild */
const u8  lvl_anim_len[5]   = { 3, 3, 3, 3, 3 };
const u16 lvl_anim_frames[5][3] = {  /* Streifen-Tile-Nrn */
    { 109, 111, 113 },  /* Anim 0: Head-Tile 109 */
    { 110, 112, 114 },  /* Anim 1: Head-Tile 110 */
    { 115, 117, 119 },  /* Anim 2: Head-Tile 115 */
    { 116, 118, 120 },  /* Anim 3: Head-Tile 116 */
    { 138, 139, 140 },  /* Anim 4: Head-Tile 138 */
};

/* ============ Sprite-Streifen-Animationen ============ */
/* Eigener Nummernraum (S1..Sn) — Bildfolgen fuer animierte Sprites/Gegner.
   Laufzeit: frame = (frame+1) % lvl_sspr_anim_len[i]; N = lvl_sspr_anim_frames[i][frame];
   N ist ein Sprite-Streifen-Index (1-basiert) -> ueber lvl_sspr_a_idx/a_pal[N-1] usw. aufloesen. */
#define LVL_SSPR_ANIM_COUNT 11
