/* ============ Metasprites (mehrteilige Sprites, z.B. 24x24-Schiff aus 3x3 Tiles) ============ */
/* Jede Zelle referenziert ein Sprite-Streifen-Tile (lvl_sspr_a_idx/a_pal/b_idx/b_pal[num-1]).
   dx/dy = Pixel-Offset relativ zur Metasprite-Ursprungsposition (oben-links).
   Aufbau: fuer i in [0, count): OAM-Sprite bei (origin_x+dx[off+i], origin_y+dy[off+i])
   mit Tile lvl_sspr_a_idx[num[off+i]-1]/a_pal[...] (+ b fuer Overlay, falls b_idx>0).
   ACHTUNG OAM-Budget: jede Zelle = 1 Sprite (Overlay-Zellen = 2) — ein 3x3-Metasprite
   ohne Splits kostet bereits 9 Slots! */
/* Metasprite 0: "Ship_L1" — 7 Zelle(n), 24x24px */
/* Metasprite 1: "Ship_L2" — 7 Zelle(n), 24x24px */
/* Metasprite 2: "Ship_M" — 7 Zelle(n), 24x24px */
/* Metasprite 3: "Ship_R1" — 7 Zelle(n), 24x24px */
/* Metasprite 4: "Ship_R2" — 7 Zelle(n), 24x24px */
/* Metasprite 5: "S81" — 2 Zelle(n), 16x8px */
/* Metasprite 6: "S" — 0 Zelle(n), 24x24px */
/* Metasprite 7: "S82" — 2 Zelle(n), 16x8px */
/* Metasprite 8: "S83" — 2 Zelle(n), 16x8px */
/* Metasprite 9: "S84" — 2 Zelle(n), 16x8px */
/* Metasprite 10: "S85" — 2 Zelle(n), 16x8px */
