/* ============ Metasprite-Animationen (mehrteilige, animierte Gegner) ============ */
/* Wie lvl_anim_*, aber die Werte in lvl_metaanim_frames sind METASPRITE-INDIZES (Index in
   lvl_meta_off/count/dx/dy/num), NICHT Tile-Nummern — pro Frame den kompletten
   Metasprite lvl_metaanim_frames[i][frame] zeichnen (draw_metasprite(), Schritt 11).
   Laufzeit pro Spawn-Instanz EIGENER frame/timer-Zaehler (wie Sprite-Streifen-Anim,
   Schritt 9) — mehrere gleichzeitige Instanzen koennen phasenversetzt animieren:
     frame = (frame + 1) % lvl_metaanim_len[i];  meta_idx = lvl_metaanim_frames[i][frame]; */
#define LVL_METAANIM_COUNT 1
